static const char str355[] = "/* libuya.h - Uya 标准库头文件 */\n";
static const char str356[] = "/* 自动生成，请勿手动修改 */\n";
static const char str357[] = "#ifndef LIBUYA_H\n";
static const char str358[] = "#define LIBUYA_H\n\n";
static const char str359[] = "/* 类型定义 */\n";
static const char str360[] = "typedef signed char int8_t;\n";
static const char str361[] = "typedef unsigned char uint8_t;\n";
static const char str362[] = "typedef signed short int16_t;\n";
static const char str363[] = "typedef unsigned short uint16_t;\n";
static const char str364[] = "typedef signed int int32_t;\n";
static const char str365[] = "typedef unsigned int uint32_t;\n";
static const char str366[] = "typedef signed long long int64_t;\n";
static const char str367[] = "typedef unsigned long long uint64_t;\n";
static const char str368[] = "typedef unsigned long size_t;\n";
static const char str369[] = "typedef long ssize_t;\n";
static const char str370[] = "\n";
static const char str371[] = "#ifndef NULL\n";
static const char str372[] = "#define NULL ((void*)0)\n";
static const char str373[] = "#endif\n\n";
static const char str374[] = "/* syscall 内联函数（x86-64） */\n";
static const char str375[] = "#ifdef __x86_64__\n";
static const char str376[] = "static inline int64_t uya_syscall0(int64_t n) {\n";
static const char str377[] = "    long ret;\n";
static const char str378[] = "    __asm__ volatile(\"syscall\" : \"=a\"(ret) : \"a\"(n) : \"rcx\", \"r11\", \"cc\", \"memory\");\n";
static const char str379[] = "    return ret;\n";
static const char str380[] = "}\n";
static const char str381[] = "static inline int64_t uya_syscall1(int64_t n, int64_t a1) {\n";
static const char str382[] = "    __asm__ volatile(\"syscall\" : \"=a\"(ret) : \"a\"(n), \"D\"(a1) : \"rcx\", \"r11\", \"cc\", \"memory\");\n";
static const char str383[] = "static inline int64_t uya_syscall2(int64_t n, int64_t a1, int64_t a2) {\n";
static const char str384[] = "    __asm__ volatile(\"syscall\" : \"=a\"(ret) : \"a\"(n), \"D\"(a1), \"S\"(a2) : \"rcx\", \"r11\", \"cc\", \"memory\");\n";
static const char str385[] = "static inline int64_t uya_syscall3(int64_t n, int64_t a1, int64_t a2, int64_t a3) {\n";
static const char str386[] = "    __asm__ volatile(\"syscall\" : \"=a\"(ret) : \"a\"(n), \"D\"(a1), \"S\"(a2), \"d\"(a3) : \"rcx\", \"r11\", \"cc\", \"memory\");\n";
static const char str387[] = "/* std.thread / microapp：函数指针间接调用（与 codegen 前导一致；勿用 inline 以免 -O2 内联退化） */\n";
static const char str388[] = "static int32_t uya_call0_i32(void *fn) {\n";
static const char str389[] = "    typedef int32_t (*uya_fn0_i32)(void);\n";
static const char str390[] = "    return ((uya_fn0_i32)fn)();\n";
static const char str391[] = "static int32_t uya_call0_i32_stack(void *fn, void *stack_top) {\n";
static const char str392[] = "#if defined(__x86_64__) || defined(_M_X64)\n";
static const char str393[] = "    uintptr_t top = ((uintptr_t)stack_top) & ~(uintptr_t)0xFUL;\n";
static const char str394[] = "    int32_t ret;\n";
static const char str395[] = "    __asm__ volatile(\n";
static const char str396[] = "        \"mov %%rsp, %%rbx\\n\\t\"\n";
static const char str397[] = "        \"mov %1, %%rsp\\n\\t\"\n";
static const char str398[] = "        \"call *%2\\n\\t\"\n";
static const char str399[] = "        \"mov %%rbx, %%rsp\\n\\t\"\n";
static const char str400[] = "        : \"=a\"(ret)\n";
